using Essco.Application.Inventory;
namespace Essco.Tests.Unit.Inventory; public sealed class InventoryCreationTests { [Fact] public async Task Requires_title() { var r = await new InventoryCreationService(new Repo()).CreateAsync(" ", "", default); Assert.False(r.Succeeded); Assert.Equal("El título es obligatorio.", r.Error); } [Fact] public async Task Normalizes_input() { var repo = new Repo(); var r = await new InventoryCreationService(repo).CreateAsync(" Trimestral ", " Nota ", default); Assert.True(r.Succeeded); Assert.Equal("Trimestral", repo.Title); Assert.Equal("Nota", repo.Comments); } private sealed class Repo : IInventoryCreationRepository { public string? Title { get; private set; } public string? Comments { get; private set; } public ValueTask<InventoryCreationResult> CreateAsync(string t, string c, CancellationToken x) { Title = t; Comments = c; return ValueTask.FromResult(new InventoryCreationResult(true, 1)); } } }
